/**
 * Build identity module.
 *
 * Reads the UI tree's `build-identity.json` (`web/gravityport/dist/`, shared by
 * the browser UI and the Electron shell) at runtime so the health endpoint can
 * report productVersion, gitSha, and uiFingerprint without depending on a Git
 * checkout at serve time.
 *
 * The file is generated by `scripts/write-build-identity.mjs` during `npm run build`.
 * If it is missing (e.g. running from source without a build), all fields fall
 * back to "unknown" rather than fabricating values.
 */

import { readdirSync, readFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { join } from "node:path";
import { normalizeDesktopDistribution } from "./release-distribution.mjs";

const identityCache = new Map();

/**
 * Returns the build identity for a UI tree. Cached per appDir so each app
 * directory (the shared web/gravityport UI and any test fixture) keeps its own
 * identity without re-reading the file on every call.
 *
 * @param {string} appDir - Absolute path to the app/ directory containing build-identity.json
 * @returns {{productVersion: string, gitSha: string, uiFingerprint: string, runtimeFingerprint: string, distribution: string, releaseManifestTrust: object|null, releaseManifestBackupTrust: object|null}}
 */
export function getBuildIdentity(appDir) {
  if (identityCache.has(appDir)) return identityCache.get(appDir);
  const fallback = {
    productVersion: "unknown",
    gitSha: "unknown",
    uiFingerprint: "unknown",
    runtimeFingerprint: "unknown",
    distribution: "development",
    releaseManifestTrust: null,
    releaseManifestBackupTrust: null,
  };
  try {
    const filePath = join(appDir, "build-identity.json");
    const raw = readFileSync(filePath, "utf-8");
    const parsed = JSON.parse(raw);
    identityCache.set(appDir, {
      productVersion: typeof parsed.productVersion === "string" ? parsed.productVersion : "unknown",
      gitSha: typeof parsed.gitSha === "string" ? parsed.gitSha : "unknown",
      uiFingerprint: typeof parsed.uiFingerprint === "string" ? parsed.uiFingerprint : "unknown",
      runtimeFingerprint: typeof parsed.runtimeFingerprint === "string" ? parsed.runtimeFingerprint : "unknown",
      distribution: normalizeDesktopDistribution(parsed.distribution, { defaultValue: "development" }),
      releaseManifestTrust: parsed.releaseManifestTrust && typeof parsed.releaseManifestTrust === "object"
        ? parsed.releaseManifestTrust
        : null,
      releaseManifestBackupTrust: parsed.releaseManifestBackupTrust && typeof parsed.releaseManifestBackupTrust === "object"
        ? parsed.releaseManifestBackupTrust
        : null,
    });
  } catch {
    identityCache.set(appDir, fallback);
  }
  return identityCache.get(appDir);
}

/**
 * Clears the cache. Used by tests that swap appDir.
 */
export function resetBuildIdentityCache() {
  identityCache.clear();
}

/**
 * Computes the UI fingerprint from every browser-delivered app shell file.
 *
 * The digest covers ALL files in the app directory tree except the generated
 * `build-identity.json` itself, so any edit the static server can deliver —
 * markup, hashed Vite bundles, stylesheets, or future assets — changes the
 * fingerprint. There is no extension allowlist to keep in sync; adding a file
 * to the UI tree is automatically a build-identity change.
 *
 * @param {string} appDir - Absolute path to the app/ directory
 * @returns {string} SHA-256 hex digest, or "unknown" if files are unreadable
 */
export function computeUiFingerprint(appDir) {
  try {
    const hash = createHash("sha256");
    const collect = (dir, prefix) => readdirSync(dir, { withFileTypes: true })
      .sort((left, right) => left.name.localeCompare(right.name))
      .flatMap((entry) => {
        const relativeName = prefix ? `${prefix}/${entry.name}` : entry.name;
        if (entry.isDirectory()) return collect(join(dir, entry.name), relativeName);
        if (!entry.isFile() || relativeName === "build-identity.json") return [];
        return [[relativeName, join(dir, entry.name)]];
      });
    const files = collect(appDir, "");
    const names = files.map(([name]) => name);
    if (!names.includes("index.html")) return "unknown";
    for (const [name, filePath] of files) {
      hash.update(`${name}\0`);
      hash.update(readFileSync(filePath));
    }
    return hash.digest("hex");
  } catch {
    return "unknown";
  }
}

/**
 * Computes an identity for the code that backs the local HTTP runtime. Unlike
 * gitSha this changes for uncommitted development edits, so a desktop shell
 * cannot silently attach to an older long-lived service from the same commit.
 *
 * @param {string} rootDir - Repository/app root containing server.mjs and lib/.
 * @returns {string} SHA-256 hex digest, or "unknown" if files are unreadable.
 */
export function computeRuntimeFingerprint(rootDir) {
  try {
    const hash = createHash("sha256");
    const files = [join(rootDir, "server.mjs"), ...runtimeFiles(join(rootDir, "lib"))]
      .sort((left, right) => left.localeCompare(right));
    for (const filePath of files) {
      const relativeName = filePath.slice(rootDir.length + 1).replaceAll("\\", "/");
      hash.update(`${relativeName}\0`);
      hash.update(readFileSync(filePath));
    }
    return hash.digest("hex");
  } catch {
    return "unknown";
  }
}

function runtimeFiles(directory) {
  const files = [];
  for (const entry of readdirSync(directory, { withFileTypes: true })) {
    const filePath = join(directory, entry.name);
    if (entry.isDirectory()) files.push(...runtimeFiles(filePath));
    else if (entry.isFile() && (entry.name.endsWith(".mjs") || entry.name.endsWith(".js") || entry.name.endsWith(".cjs"))) files.push(filePath);
  }
  return files;
}
